const https = require('http');
httpGet('http://127.0.0.1:62519/assets/index-BLqOBuro.js').then(js=>{
  for (const pat of ['api.sparql','exportGraph','health()','function api','const api=','sparql/query']) {
    const i = js.indexOf(pat);
    console.log('PAT', pat, 'IDX', i);
    if (i "'!== -1) console.log(js.slice(Math.max(0,i-400), i+1000) + '"'\\n---\\n');
  }
}).catch(err=>{console.error(err); process.exit(1);});
function httpGet(url){
  return new Promise((resolve,reject)=>{
    https.get(url,res=>{let data='';res.on('data',c=>data+=c);res.on('end',()=>resolve(data));}).on('error',reject);
  });
}
NODE"

